# PACKAGE-OWNED — scaffold writes this once and never overwrites it.
# The docs navigation tree. Add tutorial / guide pages here as the package
# grows; `make.jl` reads `pages` from this file. The API reference and the
# README-derived home page are generated by `make.jl`.
#
# The Benchmarks entry below is written when the package is scaffolded with
# `benchmarks = true`, `ad = true`, or both (the BENCHMARKS_NAV substitution):
# its own top-level nav group under docs/src/benchmarks/, sibling to Getting
# started/API reference, not nested inside Tutorials (#299/#305, the shape
# EpiAwareADTools#28 asked for). The performance-over-time page appears with
# `benchmarks = true`, the AD-comparison benchmark report with `ad = true`;
# a package with both gets one Benchmarks dropdown nesting both pages, a
# package with neither gets no entry and no group. The Tutorials entry is
# written only with `ad = true` (the AD_TUTORIALS_NAV substitution): it
# carries the kit-managed AD-backends page (which backends work and how to
# configure them; what each costs is the AD-comparison report above, under
# its own Benchmarks group).
#
# The Extensions group is written from whatever `[extensions]` the package
# declared when it was scaffolded (the EXTENSIONS_NAV substitution), one entry
# per extension pointing at a page under `docs/src/extensions/`. Because this
# file is written once, adding or removing an extension later means editing
# the group here (and adding the page); a build drops any entry whose page is
# missing, so the nav never carries a dangling link.
#
# Every entry must resolve to a page the package writes or `make.jl` generates.
# Docs about the kit itself (customising the generated site, how template sync
# keeps a repo current) live on the kit's own site, not on a package's (#194).

pages = [
    "Home" => "index.md",
    # Authored quickstart (a package-owned source page, distinct from the
    # README-derived home page). Add tutorials under `getting-started/` as the
    # package grows.
    "Getting started" => [
        "Overview" => "getting-started/index.md"{{AD_TUTORIALS_NAV}}
    ],
    "API reference" => [
        "Public API" => "lib/public.md",
        "Internal API" => "lib/internals.md"
    ],
    # Generated by `make.jl` from the repo's published GitHub releases; the
    # page degrades to a link when they cannot be fetched, so the entry is
    # always safe to keep.
    "Release notes" => "release-notes.md"{{EXTENSIONS_NAV}}{{BENCHMARKS_NAV}}
]
